PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, telegram_id TEXT NOT NULL UNIQUE, username TEXT, first_name TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admins(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, is_owner INTEGER NOT NULL DEFAULT 0, permissions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT, parent_event_id INTEGER REFERENCES events(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', starts_at TEXT, ends_at TEXT, location TEXT, cover_url TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','completed','archived')), registration_open INTEGER NOT NULL DEFAULT 0, participant_limit INTEGER, settings_json TEXT NOT NULL DEFAULT '{}', created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS registrations(id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled')), answers_json TEXT NOT NULL DEFAULT '{}', created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(event_id,user_id));
CREATE TABLE IF NOT EXISTS event_modules(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,module_key TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(event_id,module_key));
CREATE TABLE IF NOT EXISTS form_versions(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,version INTEGER NOT NULL,schema_json TEXT NOT NULL DEFAULT '[]',is_locked INTEGER NOT NULL DEFAULT 0,UNIQUE(event_id,version));
CREATE TABLE IF NOT EXISTS templates(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,config_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,title TEXT NOT NULL DEFAULT '',body TEXT NOT NULL,media_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS draws(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,mode TEXT NOT NULL DEFAULT 'secret',result_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS votes(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,title TEXT NOT NULL,options_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',deadline TEXT);
CREATE TABLE IF NOT EXISTS questions(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id),question_text TEXT NOT NULL,anonymity_mode TEXT NOT NULL DEFAULT 'admins_can_see');
CREATE TABLE IF NOT EXISTS achievements(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',image_url TEXT);
CREATE TABLE IF NOT EXISTS user_achievements(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,achievement_id INTEGER NOT NULL REFERENCES achievements(id) ON DELETE CASCADE,PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS scheduled_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,body TEXT NOT NULL,scheduled_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'scheduled');
